# --------------------------------------------------------------------------------------------------
# Institutions.  founded = year, or None where the bible gives no date.  tag: "Fixed" when the bible
# names the institution, "Example" when it is an invented or codex-derived business or local.
# owners / leaders are person keys.  trade names a business type in prices_1975.json (Part VI 4.4 rows trade_<name>_*), where the bible has one.
# --------------------------------------------------------------------------------------------------
def I(key, name, category, place, founded, notes, band="MEDIUM", trade=None, owners=(), leaders=(), basis=None,
      liquidity="STABLE_BASELINE", asset_base="MIXED", tag="Fixed"):
    if basis is None:
        basis = "bible" if founded is not None else "not_stated_in_bible"
    return dict(key=key, name=name, category=category, place=place, founded=founded, founded_basis=basis, notes=notes,
                band=band, trade=trade, owners=list(owners), leaders=list(leaders), liquidity=liquidity,
                asset_base=asset_base, tag=tag)


