# --------------------------------------------------------------------------------------------------
# Persons.  Every one is an Example (Part III 4.6, Part V 0.2) and is replaceable at seed.
#   P(key, name, sex, age, role, institutions, location, public, current, tier, source)
#   source "seat" = a Part III 4.6 suggested starting seat; "carried" = a man of the old codex cast carried
#   as an Example; "added" = added Example to give the institution structure.
# --------------------------------------------------------------------------------------------------
def P(key, name, sex, age, role, insts, loc, public, current, tier="DORMANT", source="carried"):
    return dict(key=key, name=name, sex=sex, age=age, role=role, insts=list(insts), loc=loc, public=public, current=current,
                tier=tier, source=source)


